const catalog = { items: ITEMS, byId, dependentsOf, validValue, dimensions: DIMENSIONS, archetypes: ARCHETYPES };

module.exports = { DIMENSIONS, ARCHETYPES, ITEMS, byId, dependentsOf, validValue, applicability, catalog };

